const listCanvasViewLinkIDs = `-- name: ListCanvasViewLinkIDs :many
SELECT l.id FROM links l JOIN canvases c ON c.workspace_id=l.workspace_id AND c.id=$1
WHERE l.workspace_id=$2
  AND NOT (coalesce(c.settings -> 'hiddenLinkKinds','[]'::jsonb) ? l.kind)
  AND EXISTS (SELECT 1 FROM placements p WHERE p.workspace_id=l.workspace_id AND p.canvas_id=c.id AND p.node_id=l.source_node_id)
  AND (c.area_id IS NOT NULL OR EXISTS (SELECT 1 FROM placements p WHERE p.workspace_id=l.workspace_id AND p.canvas_id=c.id AND p.node_id=l.target_node_id))
  AND NOT EXISTS (SELECT 1 FROM placements p WHERE p.workspace_id=l.workspace_id AND p.canvas_id=c.id AND p.link_id=l.id AND p.hidden)
UNION
SELECT l.id FROM links l JOIN canvases c ON c.workspace_id=l.workspace_id AND c.id=$1
WHERE l.workspace_id=$2 AND c.area_id IS NOT NULL
  AND NOT (coalesce(c.settings -> 'hiddenLinkKinds','[]'::jsonb) ? l.kind)
  AND EXISTS (SELECT 1 FROM placements p WHERE p.workspace_id=l.workspace_id AND p.canvas_id=c.id AND p.node_id=l.target_node_id)
  AND NOT EXISTS (SELECT 1 FROM placements p WHERE p.workspace_id=l.workspace_id AND p.canvas_id=c.id AND p.link_id=l.id AND p.hidden)
ORDER BY id
`

type ListCanvasViewLinkIDsParams struct {
	CanvasID    uuid.UUID
	WorkspaceID uuid.UUID
}

func (q *Queries) ListCanvasViewLinkIDs(ctx context.Context, arg ListCanvasViewLinkIDsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listCanvasViewLinkIDs, arg.CanvasID, arg.WorkspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

